"""Safety constants shared by the validator and the tests."""

# Words and phrases that would turn a question into a conclusion. Matched case-insensitively.
BANNED_PHRASES = (
    "error", "wrong", "mistake", "incorrect", "overcharg", "fraud", "illegal", "unlawful", "scam",
    "refund", "don't pay", "do not pay", "should not pay", "shouldn't pay",
    "you don't owe", "you do not owe", "billed too much", "invalid",
)

# Shown by the app itself (never generated by a model).
DISCLAIMER = (
    "This explanation was generated from the data in your EOB. It is not medical, legal, or billing "
    "advice, and it does not say whether any bill is accurate. For questions about your bill, contact "
    "your insurer or the provider's billing office."
)


def find_banned(text: str) -> list[str]:
    lowered = text.lower().replace("\u2019", "'")
    return sorted(phrase for phrase in BANNED_PHRASES if phrase in lowered)
